import { describe, expect, it } from 'vitest'

import { formatRecordSummary, parseRecordSummary, todayLocalDate } from './recordSummaryMeta'

describe('recordSummaryMeta', () => {
  it('round-trips status, severity, doctor and free text', () => {
    const summary = formatRecordSummary({
      status: 'Active',
      severity: 'Moderate',
      doctor: 'Dr. Perera',
      cleanSummary: 'Synthetic note.\nSecond line.',
    })

    expect(summary).toBe('Status: Active · Severity: Moderate · Doctor: Dr. Perera\nSynthetic note.\nSecond line.')
    expect(parseRecordSummary(summary)).toEqual({
      status: 'Active',
      severity: 'Moderate',
      doctor: 'Dr. Perera',
      cleanSummary: 'Synthetic note.\nSecond line.',
    })
  })

  it('writes no metadata line when nothing is chosen', () => {
    expect(formatRecordSummary({ cleanSummary: 'Only text' })).toBe('Only text')
    expect(formatRecordSummary({})).toBe('')
  })

  it('does not invent a status or severity for a record that has none', () => {
    expect(parseRecordSummary('Plain synthetic note')).toEqual({
      status: '',
      severity: '',
      doctor: '',
      cleanSummary: 'Plain synthetic note',
    })
    expect(parseRecordSummary(null).status).toBe('')
  })

  it('leaves free text that merely mentions a label untouched', () => {
    const text = 'Doctor: said to rest, then review in two weeks'
    const parsed = parseRecordSummary(`Seen at clinic. ${text}`)
    expect(parsed.doctor).toBe('')
    expect(parsed.cleanSummary).toBe(`Seen at clinic. ${text}`)
  })

  it('reads the older "Provider" label', () => {
    expect(parseRecordSummary('Status: Resolved · Provider: Dr. Silva').doctor).toBe('Dr. Silva')
  })

  it('keeps separators out of stored values', () => {
    const summary = formatRecordSummary({ doctor: 'Dr. A · Severity: Severe' })
    expect(summary.split('\n')).toHaveLength(1)
    expect(parseRecordSummary(summary).doctor).toBe('Dr. A Severity: Severe')
  })

  it('uses the local calendar day, not the UTC day', () => {
    const lateEvening = new Date(2026, 9, 2, 23, 30)
    expect(todayLocalDate(lateEvening)).toBe('2026-10-02')
  })
})
